/* THROWAWAY UI prototype. All OCR / Gemini / speech / rendering actions are simulations. No network calls or browser persistence. */
const $ = s => document.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons = {
 book:'M4 3h7a3 3 0 0 1 3 3v15a4 4 0 0 0-4-2H4z M14 6a3 3 0 0 1 3-3h3v16h-2a4 4 0 0 0-4 2',
 file:'M14 2H5v20h14V7z M14 2v6h5 M8 12h8 M8 16h6',
 grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',
 check:'M5 12l4 4L19 6', arrow:'M5 12h14 M13 6l6 6-6 6',left:'M15 5l-7 7 7 7',right:'M9 5l7 7-7 7',
 plus:'M12 4v16 M4 12h16',settings:'M12 3v3 M12 18v3 M3 12h3 M18 12h3 M5.6 5.6l2.1 2.1 M16.3 16.3l2.1 2.1 M5.6 18.4l2.1-2.1 M16.3 7.7l2.1-2.1 M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',
 alert:'M12 3L2 21h20z M12 9v5 M12 17v1',spark:'M12 2l3 7 7 3-7 3-3 7-3-7-7-3 7-3z',
 play:'M8 4l12 8-12 8z',pause:'M8 4v16 M16 4v16',mic:'M9 5a3 3 0 0 1 6 0v7a3 3 0 0 1-6 0z M5 10v2a7 7 0 0 0 14 0v-2 M12 19v3 M8 22h8',
 video:'M3 5h13v14H3z M16 10l5-3v10l-5-3',merge:'M4 4h6v6H4z M14 14h6v6h-6z M7 10v7h7 M14 4h6v6h-6z',
 image:'M3 3h18v18H3z M3 17l6-6 4 4 3-3 5 5 M16 7h.01',upload:'M12 16V3 M7 8l5-5 5 5 M4 16v5h16v-5',
 rotate:'M3 10a9 9 0 1 1 1 8 M3 4v6h6',close:'M5 5l14 14 M19 5L5 19',up:'M6 15l6-6 6 6',down:'M6 9l6 6 6-6',folder:'M3 6h7l2 3h9v12H3z',download:'M12 3v13 M7 11l5 5 5-5 M3 18v3h18v-3'
};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.55" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name] || icons.file}"/></svg>`;
const btn = (label,act,opts={}) => `<button type="button" data-act="${act}" ${opts.id?`data-id="${opts.id}"`:''} class="${opts.class||''}" ${opts.disabled?'disabled':''} ${opts.title?`title="${esc(opts.title)}"`:''}>${opts.icon?icon(opts.icon):''}${label}</button>`;
const pill = (text,type='') => `<span class="pill ${type}"><span class="dot"></span>${text}</span>`;
const sample = `我們總以為，只有走得夠快，才能抵達想去的地方。於是把日子排得很滿，把每一段空白，都當成尚未完成的事情。\n\n直到某個清晨，我幵始練習，把窗打開，讓風先進來。桌上的書停在昨天讀過的那一頁，茶還溫著，世界並沒有因為我的慢，而少了什麼。\n\n慢下來，並不是什麼都不做。而是在每一次選擇之前，留一點時間，聽見自己的聲音。\n\nTake your time. Some things become clearer when we learn to listen. 日子也是如此。`;
const text2 = `一條熟悉的路，走慢一點，也會有新的風景。\n\n我們不必急著給每一件事答案。有些問題，值得帶在身邊，走過一個又一個季節。\n\n當閱讀變成聆聽，一頁又一頁的文字，便有了新的呼吸。`;
let serial = 20;
const settingsHash = b => JSON.stringify([b.voice,b.rate,b.sentence,b.paragraph]);
function batch(id,name,source,start,end,text,done=false) {
 const b={id,name,source,start,end,text,original:text,rev:1,confirmed:done?1:null,unresolved:[],voice:'zh-TW-HsiaoChenNeural',rate:'0',sentence:0,paragraph:500,media:'image',resolution:'1080',mode:'loop',audio:null,video:null,candidate:null,saved:true};
 if(done){b.audio={id:'audio-'+id,rev:1,settings:settingsHash(b),duration:id==='b1'?372:411};b.video={id:'video-'+id,audioId:b.audio.id,settings:mediaHash(b),duration:b.audio.duration};}
 return b;
}
function mediaHash(b){return JSON.stringify([b.media,b.resolution,b.mode,!!b.mediaAlt]);}
const params = new URLSearchParams(location.search);
const state = {
 variant:['A','B','C'].includes(params.get('variant'))?params.get('variant'):'A',
 stage:['source','proof','voice','video','merge'].includes(params.get('step'))?params.get('step'):'proof',selected:'b2',
 batches:[batch('b1','第一章・留一點空白','PDF',1,20,text2,true),batch('b2','第二章・緩慢的練習','PDF',21,50,sample),batch('b3','補充・給自己的信','TXT',null,null,text2),batch('b4','第三章・重新聆聽','PDF',51,80,text2,true)],
 mergeIds:['b1','b4'],gap:.5,totalResolution:'1080',total:null,job:null,play:false,page:27,
 defaults:{voice:'zh-TW-HsiaoChenNeural',rate:'0',sentence:0,paragraph:500},sourceType:'PDF',gemini:{configured:true,model:'Gemini 示範模型',connected:true},lastEvent:'開啟示範書籍；目前為第二批次，PDF 第 27 頁待確認。'
};
state.batches[1].rev=3;state.batches[1].unresolved=[27];state.batches[2].confirmed=1;
const current=()=>state.batches.find(b=>b.id===state.selected);
const validAudio=b=>!!(b.audio&&b.confirmed===b.rev&&b.audio.rev===b.rev&&b.audio.settings===settingsHash(b));
const validVideo=b=>!!(b.video&&validAudio(b)&&b.video.audioId===b.audio.id&&b.video.settings===mediaHash(b));
const range=b=>b.source==='PDF'?`PDF 第 ${b.start}–${b.end} 頁`:'TXT 匯入・無頁碼';
const duration=s=>{const m=Math.floor(s/60);const r=s-m*60;return `${String(m).padStart(2,'0')}:${r.toFixed(r%1?1:0).padStart(r%1?4:2,'0')}`;};
const ordered=()=>state.mergeIds.map(id=>state.batches.find(b=>b.id===id)).filter(Boolean);
const mergeDuration=()=>ordered().reduce((n,b)=>n+(b.video?.duration||0),0)+Math.max(0,state.mergeIds.length-1)*state.gap;
const mergeSignature=()=>JSON.stringify([state.mergeIds.map(id=>{const b=state.batches.find(x=>x.id===id);return [id,b.rev,b.confirmed,b.audio?.id,b.video?.id,validVideo(b)];}),state.gap,state.totalResolution]);
state.total={signature:mergeSignature(),duration:mergeDuration(),filename:'緩慢的練習_總影片.mp4'};
const totalValid=()=>!!state.total&&state.total.signature===mergeSignature();
function batchStatus(b){if(validVideo(b))return pill('影片完成','ok');if(b.video||b.audio)return pill('成品待更新','warn');if(b.unresolved.length)return pill(`${b.unresolved.length} 頁待檢查`,'warn');if(b.confirmed===b.rev)return pill('朗讀稿已確認','blue');return pill('校對中');}
function toast(message){state.lastEvent=message;$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3300);updateState();}
function stateView(){return {prototype:true,variant:state.variant,stage:state.stage,selected:state.selected,defaults:state.defaults,batches:state.batches.map(b=>({...b,audioCurrent:validAudio(b),videoCurrent:validVideo(b)})),merge:{selected:state.mergeIds,gap:state.gap,resolution:state.totalResolution,duration:mergeDuration(),output:state.total,current:totalValid()},gemini:state.gemini,job:state.job,lastEvent:state.lastEvent};}
function updateState(){window.prototypeState=stateView();const node=$('#state-json');if(node)node.textContent=JSON.stringify(window.prototypeState,null,2);document.querySelectorAll('[data-total-badge]').forEach(n=>n.innerHTML=state.total?(totalValid()?pill('總影片已更新','ok'):pill('總影片待更新','warn')):pill('尚未合併'));}
function notice(){return `<div class="prototype-notice"><span><strong>PROTOTYPE</strong> 可操作介面原型・所有處理皆為模擬，重新整理即重設</span><span class="notice-question">比較版型：哪一種最適合分批完成一本書？</span></div>`;}
function brand(){return `<div class="brand"><span class="brand-mark">${icon('book')}</span>ebook2mp4</div>`;}
function steps(){return `<nav class="steps" aria-label="製作步驟">${[['source','來源','PDF / TXT'],['proof','校對','人工 / Gemini'],['voice','語音','MP3 / SRT'],['video','影片','批次 MP4']].map(([key,name,hint],i)=>`<button class="step ${state.stage===key?'active':''}" data-act="step" data-id="${key}" ${state.stage===key?'aria-current="step"':''}><span class="num">${i+1}</span>${name}<span>${hint}</span></button>`).join('')}</nav>`;}
function batchList(){return state.batches.map(b=>`<button class="batch-item ${b.id===state.selected?'active':''}" data-act="batch" data-id="${b.id}" ${b.id===state.selected?'aria-current="true"':''}><span class="range">${range(b)}</span><span class="name">${esc(b.name)}</span>${batchStatus(b)}</button>`).join('');}
function heading(){const names={source:['選好來源，從這裡開始。','PDF 與 TXT 都能成為同一本書的製作批次。'],proof:['讓文字，準備好被聽見。','對照原頁、修正辨識結果，再確認這一次的朗讀稿。'],voice:['找到這本書的聲音。','試聽與正式輸出，沿用相同的人聲、語速與節奏。'],video:['為聲音，留一個畫面。','重用已完成的音訊，搭配一張圖片或一支背景影片。'],merge:['把每一段，接成一本書。','挑選已完成的批次，確認順序與停頓，再合併為總影片。']};return names[state.stage];}
function topbar(){return `<header class="topbar"><div><div class="breadcrumb">書籍專案 / 緩慢的練習</div><div class="book-title">${state.stage==='merge'?'總影片製作':esc(current().name)}</div></div><div class="row"><span data-total-badge></span>${btn('專案設定','settings',{icon:'settings',class:'small'})}${btn('已暫存於原型','save',{class:'small',icon:'check'})}</div></header>`;}
function paper(){return `<div class="paper-preview"><article class="paper" aria-label="示範 PDF 頁面"><div class="chapter">CHAPTER 02 · A SLOWER LIFE</div><h3>緩慢的練習</h3><p>我們總以為，只有走得夠快，才能抵達想去的地方。於是把日子排得很滿，把每一段空白，都當成尚未完成的事情。</p><p style="margin-top:14px">直到某個清晨，我<mark>開始</mark>練習，把窗打開，讓風先進來。桌上的書停在昨天讀過的那一頁，茶還溫著，世界並沒有因為我的慢，而少了什麼。</p><div class="page-number">— ${state.page} —</div></article></div>`;}
function jobPanel(type){const j=state.job;if(!j||j.type!==type)return '';return `<div class="note" style="margin-top:15px"><div class="row between"><strong>${j.status==='running'?'模擬處理中':j.status==='cancelled'?'已取消，可續作':'模擬完成'}</strong><span>${j.done} / ${j.total}</span></div><div class="progress"><span style="width:${j.done/j.total*100}%"></span></div><p>${j.type==='audio'?'已完成區塊保留；不完整區塊不列為成功。':'此為介面進度示範，不會呼叫外部服務。'}</p><div class="row wrap" style="margin-top:9px">${j.status==='running'?btn('取消','cancel-job',{class:'small danger'}):j.status==='cancelled'?btn('繼續處理','resume-job',{class:'small'}):''}</div></div>`;}
function proofScene(){const b=current();const candidate=b.candidate;return `<div class="scene"><section><div class="section-title"><h2>文字校對</h2><span class="meta">${range(b)} · v<span data-live-version>${b.rev}</span></span></div>${b.unresolved.length?`<div class="inline-alert">${icon('alert')}<div><strong>第 ${b.unresolved.join('、')} 頁需要確認</strong><br>這一頁只有少量文字，請比對圖片正文後再確認朗讀稿。</div></div>`:''}<div class="panel"><div class="panel-header row between"><span class="row" style="font-size:12px">${icon('file')}<strong>原頁對照 / 校對稿</strong></span>${pill(b.saved?'已暫存':'編輯中')}</div><div class="proof-grid">${b.source==='PDF'?paper():`<div class="paper-preview"><div class="paper"><div class="chapter">ORIGINAL TXT</div><h3>來源文字</h3><p>${esc(b.original).replaceAll('\n','<br>')}</p></div></div>`}<div class="editor"><div class="editor-tools">${icon('file')}<span>校對稿 v<span data-live-version>${b.rev}</span></span><span class="spacer"></span>${btn('回復原文','undo',{class:'small ghost',title:'回復示範擷取原稿'})}</div><label class="sr-label" for="draft-editor" hidden>批次校對稿</label><textarea id="draft-editor" aria-label="批次校對稿" spellcheck="false">${esc(b.text)}</textarea><div class="editor-footer"><span data-char-count>${b.text.length} 字元 · ${b.text.split(/\n\s*\n/).length} 段落</span><span>修改後須重新確認朗讀稿</span></div></div></div>${b.source==='PDF'?`<div class="page-tabs"><span class="meta" style="margin-right:8px">PDF 頁次</span>${[25,26,27,28,29].map(n=>`<button class="${n===state.page?'active':''}" data-act="page" data-id="${n}" aria-label="預覽 PDF 第 ${n} 頁">${n}${b.unresolved.includes(n)?' · 待查':''}</button>`).join('')}<span class="spacer"></span>${btn('檢視原頁','show-page',{class:'small ghost'})}</div>`:''}</div><div class="proof-actions"><div class="row wrap">${btn('匯出 TXT','export-txt',{icon:'download',class:'small'})}${btn('重新載入','reload-txt',{icon:'rotate',class:'small'})}</div><span class="meta">${b.source==='PDF'?'PDF 頁次不一定等於書上印刷頁碼':'TXT 不建立虛構頁碼對應'}</span></div></section><aside class="inspector"><section class="panel"><div class="panel-body"><div class="section-title"><h3>Gemini 輔助校對</h3>${pill('示範','blue')}</div><p>修正錯字與標點，保留原文的意思與語氣。修改由你決定。</p>${candidate?`<div class="diff-box">${candidate.status==='pending'?`建議修改 1 處<br>我<del>幵始</del><ins>開始</ins>練習，把窗打開。`:`${icon('check')} ${candidate.status==='accepted'?'建議已採用，仍需確認朗讀稿':'建議已拒絕，原稿保持不變'}`}</div>${candidate.status==='pending'?`<div class="row">${btn('拒絕','reject-candidate',{class:'small'})}${btn('採用本段','accept-candidate',{class:'small',icon:'check'})}</div>`:''}`:''}${btn('以 Gemini 校對','gemini',{icon:'spark',class:'primary',disabled:state.job?.status==='running'})}${jobPanel('gemini')}<div class="divider"></div><div class="meta">只產生候選結果，不自動改稿。<br>原型不會送出文字或呼叫 Gemini。</div></div></section><section class="panel"><div class="panel-body"><h3>朗讀稿確認</h3><div class="info-line"><span class="muted">目前校對版本</span><span class="value">v<span data-live-version>${b.rev}</span></span></div><div class="info-line"><span class="muted">朗讀狀態</span><span class="value" data-confirm-status>${b.confirmed===b.rev?'已確認 v'+b.rev:'尚未確認'}</span></div>${b.unresolved.length?`<div class="note warn">還有 ${b.unresolved.length} 頁待檢查。<div style="margin-top:8px">${btn('確認此頁內容','resolve-page',{class:'small',icon:'check'})}</div></div>`:`<div class="ready-check">${icon('check')}<span>沒有未處理的異常頁，可確認本次文字版本。</span></div>`}${btn(b.confirmed===b.rev?'已確認為朗讀稿':'確認為本次朗讀稿','confirm',{class:'primary',icon:'check',disabled:!!b.unresolved.length||b.confirmed===b.rev})}<p style="margin-top:10px">確認會固定當下文字，供這一批次朗讀使用。</p></div></section></aside></div>`;}
function sourceScene(){return `<div class="scene"><section><div class="section-title"><h2>新增製作批次</h2><span class="meta">一本書，多次完成</span></div><div class="source-types"><button class="source-option" data-act="source-pdf">${icon('file')}<h3>從 PDF 開始</h3><p>選頁、文字擷取或 OCR<br>再進入校對</p></button><button class="source-option" data-act="source-txt">${icon('file')}<h3>從 TXT 開始</h3><p>匯入已整理的文字<br>直接開始校對</p></button></div><div class="panel source-preview">${state.sourceType==='PDF'?`<div class="file-card">${icon('file')}<div><h3>緩慢的練習_示範書稿.pdf</h3><p>120 頁 · 18.4 MB · 可讀取 · 示範素材</p></div><span class="spacer"></span>${pill('PDF','blue')}</div><div class="form-grid"><label class="form-field">起始頁<input id="pdf-start" type="number" min="1" max="120" value="81"></label><label class="form-field">結束頁<input id="pdf-end" type="number" min="1" max="120" value="100"></label><label class="form-field">辨識模式<select><option>自動：逐頁判斷文字或 OCR</option><option>全部強制 OCR</option></select></label><label class="form-field">OCR 語言<select><option>繁體中文＋英文</option><option>簡體中文＋英文</option><option>英文</option></select></label></div><p id="source-error" class="meta danger" role="alert"></p><div class="row between wrap"><span class="meta">起訖皆包含 · 頁碼採 PDF 實際順序</span>${btn('擷取示範頁面','extract',{class:'primary',icon:'arrow',disabled:state.job?.status==='running'})}</div>${jobPanel('extract')}`:`<div class="empty-state">${icon('upload')}<h3>匯入一份文字，建立一個批次</h3><p>原型可讀取本機 UTF-8 TXT，文字只留在目前頁面的記憶體。</p><div class="row wrap" style="justify-content:center;margin-top:20px">${btn('選擇 TXT','import-txt',{icon:'folder'})}${btn('使用示範 TXT','sample-txt',{class:'primary',icon:'plus'})}</div></div>`}</div></section><aside class="inspector"><div class="panel"><div class="panel-body"><h3>這一批會保留什麼？</h3>${[['來源副本','保留原始檔案'],['擷取原稿','可以回看、比對'],['校對稿','人工與 Gemini 共用'],['成品','每批分開保存']].map(([a,b])=>`<div class="info-line"><span>${a}</span><span class="muted">${b}</span></div>`).join('')}<div class="divider"></div><p>新增批次不會覆蓋這本書的其他成果。TXT 不需要 PDF 或 OCR。</p></div></div><div class="note">原型中的 PDF 是版面示意，沒有實際 PDF 解析或 OCR。</div></aside></div>`;}
function waveform(){return `<div class="waveform ${state.play?'playing':''}" aria-hidden="true">${Array.from({length:65},(_,i)=>`<i style="height:${15+Math.abs(Math.sin(i*1.23)*Math.cos(i*.29))*65}px"></i>`).join('')}</div>`;}
function settingsFields(b){return `<label class="form-field">朗讀人聲<select id="voice"><option value="zh-TW-HsiaoChenNeural" ${b.voice==='zh-TW-HsiaoChenNeural'?'selected':''}>曉臻 HsiaoChen · 台灣華語</option><option value="zh-TW-YunJheNeural" ${b.voice==='zh-TW-YunJheNeural'?'selected':''}>雲哲 YunJhe · 台灣華語</option><option value="en-US-JennyNeural" ${b.voice==='en-US-JennyNeural'?'selected':''}>Jenny · 美國英語</option></select><small>原型音色清單僅供示意；正式版依服務清單更新。</small></label><label class="form-field">語速<select id="rate">${[['-20','慢 20%'],['-10','慢 10%'],['0','正常'],['10','快 10%'],['20','快 20%']].map(([v,t])=>`<option value="${v}" ${b.rate===v?'selected':''}>${t}</option>`).join('')}</select></label><div class="preset-buttons">${btn('自然','preset-natural',{class:b.sentence===0&&b.paragraph===500?'active':''})}${btn('舒緩','preset-relaxed',{class:b.sentence===200&&b.paragraph===800?'active':''})}</div><div class="form-grid"><label class="form-field">句尾額外停頓<input id="sentence" type="number" min="0" max="1500" step="100" value="${b.sentence}"><small>毫秒 · 0–1,500</small></label><label class="form-field">段落額外停頓<input id="paragraph" type="number" min="0" max="3000" step="100" value="${b.paragraph}"><small>毫秒 · 0–3,000</small></label></div>`;}
function audioFiles(b){return b.audio?`<div class="output-file">${icon('mic')}<div><strong>${esc(b.name)}.mp3</strong><small>${duration(b.audio.duration)} · 來源 v${b.audio.rev}</small></div>${pill(validAudio(b)?'有效':'待更新',validAudio(b)?'ok':'warn')}</div><div class="output-file">${icon('file')}<div><strong>${esc(b.name)}.srt</strong><small>UTF-8 · 同一時間軸</small></div></div>`:`<div class="empty-state">${icon('mic')}<h3>還沒有這一批的音訊</h3><p>確認朗讀稿後，即可產生 MP3 與 SRT。</p></div>`;}
function voiceScene(){const b=current();return `<div class="scene"><section><div class="section-title"><h2>短文試聽</h2>${pill('聲音示意','blue')}</div><div class="panel"><p class="sample-text">${esc(b.text.slice(0,100))}</p>${waveform()}<div class="playback">${btn(state.play?'停止示意':'模擬試聽','play',{icon:state.play?'pause':'play',class:'small'})}<span class="muted">示範播放狀態，不播放真實人聲</span><span class="spacer"></span><span>00:32</span></div></div><div class="section-title" style="margin-top:25px"><h2>批次音訊與字幕</h2><span class="meta" data-confirm-status>${b.confirmed===b.rev?'朗讀稿 v'+b.rev+' 已確認':'需要先確認朗讀稿'}</span></div><div class="panel"><div class="panel-body">${audioFiles(b)}${jobPanel('audio')}<div class="row wrap" style="margin-top:17px">${btn(validAudio(b)?'重新產生音訊':'產生 MP3／SRT','generate-audio',{icon:'mic',class:'primary',disabled:b.confirmed!==b.rev||state.job?.status==='running'})}${btn('返回校對','to-proof',{class:'ghost'})}</div></div></div><p class="footer-note">只從已確認的文字產生語音；額外停頓會反映在字幕時間中。</p></section><aside class="inspector"><section class="panel"><div class="panel-body"><h3 style="margin-bottom:18px">這一批的聲音</h3>${settingsFields(b)}<div class="note">同一位置是句尾與段落時，取較長停頓。最後一段不額外補尾部靜音。</div></div></section><section class="panel"><div class="panel-body"><h3>全書語音預設</h3><p>新批次沿用預設；既有批次保留各自設定。</p>${btn('將本批設定為全書預設','set-defaults',{class:'small',icon:'check'})}</div></section></aside></div>`;}
function artwork(){return `<div class="book-art" style="${current().mediaAlt?'background:#c7d6d2':''}" role="img" aria-label="緩慢的練習書封示意"><div class="art-lines"></div><div class="art-title">緩慢的<br>練習</div><div class="art-meta">A SLOWER LIFE · AUDIOBOOK</div></div>`;}
function videoScene(){const b=current();return `<div class="scene"><section><div class="section-title"><h2>畫面預覽</h2><span class="meta">${b.resolution==='1080'?'1920 × 1080':'1280 × 720'} · 30 fps</span></div><div class="panel"><div class="panel-body"><div class="media-preview">${artwork()}<div class="preview-overlay"><span>${b.media==='image'?'單張圖片・持續至音訊結束':'背景影片・'+(b.mode==='loop'?'循環播放':'停在最後一格')}</span><span>${duration(b.audio?.duration||0)}</span></div></div><div class="media-options">${btn('圖片','media-image',{icon:'image',class:b.media==='image'?'active':''})}${btn('背景影片','media-video',{icon:'video',class:b.media==='video'?'active':''})}</div><div class="file-card" style="margin-bottom:0">${icon(b.media==='image'?'image':'video')}<div><h3>${b.media==='image'?(b.mediaAlt?'緩慢的練習_封面B.png':'緩慢的練習_封面.png'):'清晨的窗邊_背景.mp4'}</h3><p>${b.media==='image'?'示範素材 · PNG · 保持比例':'示範素材 · 00:18 · 原聲靜音'}</p></div><span class="spacer"></span>${btn('更換示範素材','change-media',{class:'small'})}</div></div></div><div class="panel" style="margin-top:18px"><div class="panel-body">${b.video?`<div class="output-file">${icon('video')}<div><strong>${esc(b.name)}.mp4</strong><small>${duration(b.video.duration)} · H.264 / AAC · 模擬成品</small></div>${pill(validVideo(b)?'有效':'待更新',validVideo(b)?'ok':'warn')}</div>`:`<p class="meta">輸出會沿用這一批已完成的音訊與字幕。</p>`}${jobPanel('video')}<div class="row wrap" style="margin-top:16px">${btn('產生批次 MP4','generate-video',{class:'primary',icon:'video',disabled:!validAudio(b)||state.job?.status==='running'})}${btn('前往總影片合併','to-merge',{class:'ghost',icon:'merge'})}</div>${!validAudio(b)?'<p class="footer-note">請先在「語音」完成與目前文字、設定一致的 MP3／SRT。</p>':''}</div></div></section><aside class="inspector"><section class="panel"><div class="panel-body"><h3 style="margin-bottom:17px">影片設定</h3><label class="form-field">輸出解析度<select id="resolution"><option value="1080" ${b.resolution==='1080'?'selected':''}>1080p · 1920 × 1080</option><option value="720" ${b.resolution==='720'?'selected':''}>720p · 1280 × 720</option></select></label>${b.media==='video'?`<label class="form-field">背景短於旁白時<select id="video-mode"><option value="loop" ${b.mode==='loop'?'selected':''}>循環播放</option><option value="freeze" ${b.mode==='freeze'?'selected':''}>停在最後一格</option></select></label>`:''}<div class="info-line"><span>畫面比例</span><span class="value">原比例・黑邊補齊</span></div><div class="info-line"><span>音訊來源</span><span class="value">${validAudio(b)?'有效批次 MP3':'尚未準備完成'}</span></div><div class="divider"></div><p>只更換圖片、影片或尺寸，不會重新合成語音。</p></div></section><div class="note">影片處理為模擬。原型不會讀取媒體、執行 FFmpeg 或寫入成品。</div></aside></div>`;}
function timeline(){const bs=ordered();return `<div class="timeline" aria-label="總影片批次時間軸">${bs.map((b,i)=>`${i?`<div class="timeline-gap">${state.gap}s</div>`:''}<div class="timeline-block">${esc(b.name.split('・')[0])}<small>${duration(b.video?.duration||0)}</small></div>`).join('')||'<p class="meta">先選擇至少一個批次</p>'}</div>`;}
function pageWarnings(){const pdf=ordered().filter(b=>b.source==='PDF');const msgs=[];for(let i=1;i<pdf.length;i++){const prev=pdf[i-1],next=pdf[i];if(next.start<=prev.end)msgs.push('選入批次的 PDF 頁碼有重疊或順序調整');else if(next.start>prev.end+1)msgs.push(`PDF 第 ${prev.end+1}–${next.start-1} 頁不在選取範圍`);}return [...new Set(msgs)];}
function mergeScene(){const bs=ordered(),warnings=pageWarnings();return `<div class="scene"><section><div class="section-title"><h2>選入批次與順序</h2><span class="meta">${state.mergeIds.length} 批已選</span></div><div class="panel"><div class="merge-list">${ordered().concat(state.batches.filter(b=>!state.mergeIds.includes(b.id))).map(b=>`<div class="merge-item"><input type="checkbox" data-merge-id="${b.id}" ${state.mergeIds.includes(b.id)?'checked':''} aria-label="選入${esc(b.name)}"><div><strong>${esc(b.name)}</strong><div class="meta">${range(b)} · ${b.video?duration(b.video.duration):'尚無影片'} · ${b.resolution}p</div><div style="margin-top:7px">${batchStatus(b)}</div></div><div class="reorder">${btn(icon('up'),'move-up',{id:b.id,class:'icon-only',disabled:!state.mergeIds.includes(b.id)||state.mergeIds.indexOf(b.id)===0,title:'將'+b.name+'向前移'})}${btn(icon('down'),'move-down',{id:b.id,class:'icon-only',disabled:!state.mergeIds.includes(b.id)||state.mergeIds.indexOf(b.id)===state.mergeIds.length-1,title:'將'+b.name+'向後移'})}</div></div>`).join('')}</div></div>${warnings.length?`<div class="note warn" style="margin-top:14px">${icon('alert')} ${warnings.join('；')}。<br>這是提醒；不自動補頁或刪除內容，可依你的選擇繼續。</div>`:''}<div class="section-title" style="margin-top:23px"><h2>接續時間軸</h2><span class="meta">${duration(mergeDuration())}</span></div>${timeline()}<div class="row between wrap"><span class="meta">字幕依實際長度＋交接停頓平移</span>${btn('預覽接點','preview-join',{icon:'play',class:'small',disabled:bs.length<2})}</div>${bs.length>1?`<div class="join-copy"><span>銜接檢查 · ${esc(bs[0].name)} → ${esc(bs[1].name)}</span>「${esc(bs[0].text.slice(-42))}」<br><span style="margin:8px 0">額外停頓 ${state.gap} 秒</span>「${esc(bs[1].text.slice(0,42))}」<div style="margin-top:10px">${btn('返回前批校對','edit-join',{class:'small ghost',id:bs[0].id,icon:'file'})}</div></div>`:''}</section><aside class="inspector"><section class="panel"><div class="panel-body"><h3 style="margin-bottom:20px">總影片設定</h3><label class="form-field">批次交接額外停頓<div class="row"><input id="gap" type="number" min="0" max="5" step="0.1" value="${state.gap}"><span class="meta">秒</span>${btn('套用','apply-gap',{class:'small'})}</div><small>預設 0.5 秒，可調整 0–5 秒。<br>保留原音訊頭尾，實際間隔可能更長。</small></label><label class="form-field">總影片解析度<select id="total-resolution"><option value="1080" ${state.totalResolution==='1080'?'selected':''}>1080p · 1920 × 1080</option><option value="720" ${state.totalResolution==='720'?'selected':''}>720p · 1280 × 720</option></select></label><div class="divider"></div><div class="info-line"><span class="muted">預計總長</span><span class="value">${duration(mergeDuration())}</span></div><div class="info-line"><span class="muted">額外交接</span><span class="value">${Math.max(0,bs.length-1)} 次 × ${state.gap}s</span></div>${bs.some(b=>!validVideo(b))?'<div class="note warn" style="margin-top:10px">選入批次尚有未完成或待更新影片，請先回到該批完成製作。</div>':''}${btn('合併總 MP4／SRT','generate-merge',{class:'primary',icon:'merge',disabled:!bs.length||bs.some(b=>!validVideo(b))||state.job?.status==='running'})}${jobPanel('merge')}<p style="margin-top:10px">保持批次原檔，不會重新呼叫 TTS。</p></div></section><section class="panel"><div class="panel-body"><div class="section-title"><h3>現有總影片</h3><span data-total-badge></span></div><p>${state.total?esc(state.total.filename):'尚未產生總影片'}</p><p class="meta" style="margin-top:8px">只追蹤實際選入的批次版本。未選批次的修改不影響這份成品。</p></div></section></aside></div>`;}
function scene(){return ({source:sourceScene,proof:proofScene,voice:voiceScene,video:videoScene,merge:mergeScene}[state.stage])();}
function statePanel(){return `<details class="dev-state"><summary>原型工具 · 檢視目前狀態與情境演練</summary><div class="dev-actions">${btn('回到初始示範','reset',{class:'small'})}${btn('修改第一批，觀察總影片失效','scenario-stale',{class:'small'})}${btn('模擬中斷目前任務','cancel-job',{class:'small',disabled:!state.job||state.job.status!=='running'})}</div><p class="meta">狀態只留在記憶體，沒有實際儲存、上傳或產生媒體。</p><pre id="state-json"></pre></details>`;}
function VariantA(){const [title,sub]=heading();return `${notice()}<div class="app-a"><aside class="sidebar">${brand()}<section class="project-card"><div class="eyebrow">CURRENT BOOK</div><h2>緩慢的練習</h2><p>書籍專案 · 120 頁 · 本機製作</p></section><div class="batch-title"><span>製作批次 <strong>${String(state.batches.length).padStart(2,'0')}</strong></span>${btn(icon('plus'),'new-batch',{class:'small ghost icon-only',title:'新增製作批次'})}</div><div class="batch-list">${batchList()}</div>${btn('總影片合併','to-merge',{icon:'merge',class:'merge-button ghost'})}<div class="sidebar-note">一本書，一個專案。<br>每個批次獨立校對與保存。</div></aside><main class="workspace-main">${topbar()}<div class="content"><div class="page-heading"><div><div class="eyebrow" style="margin-bottom:9px">${state.stage==='merge'?'BOOK ASSEMBLY':'BATCH WORKSPACE'}</div><h1>${title}</h1><p>${sub}</p></div><div class="heading-action">${state.stage==='proof'?btn('Gemini 設定','settings',{class:'ghost small',icon:'settings'}):btn('新增批次','new-batch',{class:'small',icon:'plus'})}</div></div>${state.stage==='merge'?'':steps()}${scene()}${statePanel()}</div></main></div>`;}
function VariantB(){const [title]=heading();const index=['source','proof','voice','video'].indexOf(state.stage);return `${notice()}<div class="app-b"><header class="topbar">${brand()}<div class="book-title">緩慢的練習 <span class="muted">/ 書籍專案</span></div><div class="row">${btn('全書合併','to-merge',{class:'small',icon:'merge'})}${btn('設定','settings',{class:'ghost small',icon:'settings'})}</div></header><main class="b-content"><div class="b-heading"><div class="eyebrow">ONE BOOK, ONE STEP AT A TIME</div><h1>${title}</h1><p class="meta">${state.stage==='merge'?'將各自完成的片段，接成完整的聆聽體驗。':'把注意力留給這一批，其餘的，稍後再來。'}</p></div><nav class="batch-tabs" aria-label="製作批次">${state.batches.map((b,i)=>`<button class="${b.id===state.selected?'active':''}" data-act="batch" data-id="${b.id}" ${b.id===state.selected?'aria-current="true"':''}>${String(i+1).padStart(2,'0')} ${esc(b.name.split('・')[0])}</button>`).join('')}${btn('+ 新增','new-batch',{class:'small'})}</nav>${state.stage==='merge'?'':steps()}${scene()}<div class="b-footer"><span class="meta">${range(current())} · 本批獨立保存<br>離開此步驟不會失去目前編輯。</span><div class="row wrap">${btn('上一步','previous-step',{class:'ghost',disabled:index<=0})}${btn(state.stage==='video'?'前往總影片':'下一步','next-step',{icon:'arrow',class:'primary'})}</div></div>${statePanel()}</main></div>`;}
function VariantC(){const ready=state.batches.filter(validVideo).length;return `${notice()}<div class="app-c"><header class="topbar">${brand()}<div class="book-title">緩慢的練習 <span class="muted"> / 製作控制台</span></div><div class="row">${btn('Gemini 設定','settings',{class:'small ghost',icon:'settings'})}${btn('新增批次','new-batch',{class:'small',icon:'plus'})}</div></header><div class="c-command"><div class="metric"><strong>${String(state.batches.length).padStart(2,'0')}</strong><span>製作批次</span></div><div class="metric"><strong>${String(ready).padStart(2,'0')} <span style="display:inline">/ ${state.batches.length}</span></strong><span>影片已完成</span></div><div class="metric"><strong>${duration(mergeDuration())}</strong><span>已選批次總長</span></div><div class="metric"><strong>${state.gap}<span style="display:inline"> s</span></strong><span>交接額外停頓</span></div><div class="spacer"></div>${btn('製作總影片','to-merge',{icon:'merge',class:'primary'})}</div><div class="c-layout"><main class="c-queue"><div class="row between"><div><div class="eyebrow" style="margin-bottom:8px">PRODUCTION QUEUE</div><h1>整本書，一眼看清。</h1></div>${pill('示範專案','blue')}</div><table class="queue-table"><thead><tr><th>批次 / 來源</th><th class="range-column">內容範圍</th><th>朗讀稿</th><th>狀態</th><th></th></tr></thead><tbody>${state.batches.map((b,i)=>`<tr class="${b.id===state.selected?'selected':''}"><td><strong>${String(i+1).padStart(2,'0')} ${esc(b.name.split('・')[0])}</strong><span class="meta">${b.source} · ${b.text.length} 字元</span></td><td class="range-column"><span class="meta">${b.source==='PDF'?b.start+'–'+b.end+' 頁':'TXT'}</span></td><td><span class="meta">${b.confirmed===b.rev?'已確認 v'+b.rev:'待確認'}</span></td><td class="status-cell">${batchStatus(b)}</td><td>${btn('開啟','batch',{id:b.id,class:'small ghost'})}</td></tr>`).join('')}</tbody></table><section class="c-assembly"><div class="row between"><h3>總影片組裝</h3><span data-total-badge></span></div>${timeline()}<div class="row between wrap"><span class="meta">${state.mergeIds.length} 批 · ${state.totalResolution}p · 額外停頓 ${state.gap}s</span>${btn('編輯合併設定','to-merge',{class:'small ghost',icon:'arrow'})}</div></section>${statePanel()}</main><aside class="c-detail"><div class="section-title"><div><div class="eyebrow" style="margin-bottom:7px">${state.stage==='merge'?'TOTAL VIDEO':'SELECTED BATCH'}</div><h2>${state.stage==='merge'?'總影片設定':esc(current().name)}</h2></div>${state.stage==='merge'?(totalValid()?pill('總影片已更新','ok'):pill('總影片待更新','warn')):batchStatus(current())}</div>${state.stage==='merge'?'':steps()}${scene()}</aside></div></div>`;}
function switcher(){const names={A:['校對工作台','原頁與文字並排'],B:['引導式流程','一次聚焦一個步驟'],C:['製作控制台','批次進度優先']};return `<nav class="variant-switcher" aria-label="原型版型切換"><span class="prototype-switch-label">版型比較</span>${btn(icon('left'),'variant-prev',{class:'nav-arrow',title:'上一個版型，方向鍵左'})}<div class="variant-name"><strong>${state.variant} · ${names[state.variant][0]}</strong><small>${names[state.variant][1]}</small></div>${btn(icon('right'),'variant-next',{class:'nav-arrow',title:'下一個版型，方向鍵右'})}<span class="variant-separator"></span>${['A','B','C'].map(v=>`<button class="variant-key ${state.variant===v?'active':''}" data-act="variant" data-id="${v}" aria-label="版型 ${v}：${names[v][0]}" aria-pressed="${state.variant===v}">${v}</button>`).join('')}</nav>`;}
function render(){document.documentElement.style.colorScheme=state.variant==='C'?'dark':'light';$('#app').innerHTML=({A:VariantA,B:VariantB,C:VariantC}[state.variant])()+((location.protocol==='file:'||['127.0.0.1','localhost'].includes(location.hostname))?switcher():'');updateState();}
function setStage(stage){state.stage=stage;const url=new URL(location.href);url.searchParams.set('step',stage);url.searchParams.set('variant',state.variant);history.replaceState({},'',url);render();}
function variant(value){state.variant=value;const url=new URL(location.href);url.searchParams.set('variant',value);history.replaceState({},'',url);render();}
function edited(b){b.rev++;b.confirmed=null;b.saved=false;document.querySelectorAll('[data-live-version]').forEach(n=>n.textContent=b.rev);document.querySelectorAll('[data-confirm-status]').forEach(n=>n.textContent='尚未確認');const count=$('[data-char-count]');if(count)count.textContent=`${b.text.length} 字元 · ${b.text.split(/\n\s*\n/).length} 段落`;const confirm=$('[data-act="confirm"]');if(confirm){confirm.disabled=!!b.unresolved.length||!b.text.trim();confirm.innerHTML=icon('check')+'確認為本次朗讀稿';}updateState();}
function startJob(type,batchId=state.selected){if(state.job?.status==='running'){toast('目前已有一個模擬任務，請先完成或取消。');return;}state.job={type,batchId,done:0,total:type==='gemini'?3:type==='audio'?6:4,status:'running',snapshot:JSON.parse(JSON.stringify(state.batches.find(b=>b.id===batchId)||current())),mergeSnapshot:{signature:mergeSignature(),duration:mergeDuration()}};render();tickJob();}
function tickJob(){clearTimeout(tickJob.timer);const j=state.job;if(!j||j.status!=='running')return;tickJob.timer=setTimeout(()=>{if(state.job!==j||j.status!=='running')return;j.done++;if(j.done>=j.total){j.status='completed';finishJob(j);}else{render();tickJob();}},460);}
function finishJob(j){const b=state.batches.find(b=>b.id===j.batchId);const s=j.snapshot;if(j.type==='gemini'){b.candidate={baseRev:s.rev,status:'pending',text:s.text.replace('幵始','開始')};toast('已產生示範候選稿；尚未修改原稿。');}if(j.type==='audio'){b.audio={id:'audio-'+(++serial),rev:s.rev,settings:settingsHash(s),duration:Math.max(45,Math.round(s.text.length*1.5))};toast('模擬 MP3／SRT 已完成，來源版本與設定已記錄。');}if(j.type==='video'){b.video={id:'video-'+(++serial),audioId:s.audio?.id,settings:mediaHash(s),duration:s.audio?.duration||0};toast('模擬批次 MP4 已完成，沒有新增 TTS 請求。');}if(j.type==='merge'){state.total={signature:j.mergeSnapshot.signature,duration:j.mergeSnapshot.duration,filename:'緩慢的練習_總影片.mp4'};toast('模擬總 MP4／SRT 已完成；批次原檔保留。');}if(j.type==='extract'){b.text=sample;b.original=sample;b.unresolved=[Math.min(b.start+6,b.end)];b.saved=true;state.selected=b.id;state.stage='proof';state.page=b.unresolved[0];toast('示範擷取完成，請對照待檢查頁；未執行實際 OCR。');}render();}
function openDialog(html){$('#dialog-content').innerHTML=html;$('#dialog').showModal();}
function settingsDialog(){openDialog(`<div class="row between"><h2>專案與 Gemini 設定</h2>${btn(icon('close'),'close-dialog',{class:'icon-only ghost',title:'關閉設定'})}</div><p class="muted">介面原型，請勿填入真實金鑰。所有欄位只保留在目前頁面。</p><label class="form-field">Gemini API Key<input type="password" value="prototype-demo-key" aria-label="Gemini API Key 示範值" autocomplete="off"><small>正式版金鑰存於本機設定，不會放進書籍專案。</small></label><label class="form-field">模型<input id="gemini-model" value="${esc(state.gemini.model)}"></label><div class="row between"><span class="meta">${state.gemini.connected?'示範連線：已就緒':'尚未測試'}</span>${btn('模擬連線測試','test-gemini',{icon:'spark'})}</div><div class="divider"></div><h3>全書語音預設</h3><p class="meta" style="margin-top:10px">${esc(state.defaults.voice)} · 語速 ${state.defaults.rate}%<br>句尾 ${state.defaults.sentence} ms / 段落 ${state.defaults.paragraph} ms</p><div class="note" style="margin-top:15px">新批次沿用全書預設。修改預設不會自動改掉已存在批次的語音設定。</div><div class="dialog-actions">${btn('完成','save-settings',{class:'primary'})}</div>`);}
function previewJoin(){const bs=ordered();if(bs.length<2)return;openDialog(`<div class="row between"><h2>批次交接預覽</h2>${btn(icon('close'),'close-dialog',{class:'ghost icon-only',title:'關閉預覽'})}</div><p class="meta">${esc(bs[0].name)} → ${esc(bs[1].name)}</p><div class="media-preview" style="margin-top:18px">${artwork()}<div class="preview-overlay"><span id="join-caption">前一批最後一格・字幕清空</span><span>額外 ${state.gap.toFixed(1)}s</span></div></div><div class="join-copy"><span>前批結尾</span>${esc(bs[0].text.slice(-65))}<span style="margin-top:15px">後批開頭</span>${esc(bs[1].text.slice(0,65))}</div><div class="note" style="margin-top:14px">保留原始頭尾音訊，額外停頓 ${state.gap} 秒。這是畫面與時間狀態示意，不播放真實音訊。</div><div class="dialog-actions">${btn('模擬接續播放','play-join',{icon:'play',class:'primary'})}</div>`);}
document.addEventListener('click',event=>{
 const button=event.target.closest('button[data-act]');if(!button||button.disabled)return;const act=button.dataset.act,id=button.dataset.id,b=current();
 if(act==='variant'){variant(id);return;}if(act==='variant-prev'||act==='variant-next'){variant(['A','B','C'][(['A','B','C'].indexOf(state.variant)+(act==='variant-next'?1:2))%3]);return;}
 if(act==='step'){setStage(id);return;}if(act==='batch'){state.selected=id;state.page=current().unresolved[0]||current().start||1;if(state.stage==='merge')state.stage='proof';render();return;}
 if(act==='to-merge'){setStage('merge');return;}if(act==='to-proof'){setStage('proof');return;}if(act==='new-batch'){setStage('source');return;}
 if(act==='previous-step'||act==='next-step'){const steps=['source','proof','voice','video','merge'];setStage(steps[Math.max(0,Math.min(4,steps.indexOf(state.stage)+(act==='next-step'?1:-1)))]);return;}
 if(act==='source-pdf'||act==='source-txt'){state.sourceType=act==='source-pdf'?'PDF':'TXT';render();return;}
 if(act==='sample-txt'){const n=batch('b'+(++serial),'新批次・TXT 示範','TXT',null,null,text2);Object.assign(n,state.defaults);state.batches.push(n);state.selected=n.id;setStage('proof');toast('已在同一本書加入 TXT 批次，不建立虛構頁碼。');return;}
 if(act==='import-txt'||act==='reload-txt'){if(act==='reload-txt'&&!b.saved){openDialog(`<h2>保留目前的編輯？</h2><p>目前有尚未儲存的修改。你可以先匯出副本，再選擇外部 TXT；原型不會直接丟掉內容。</p><div class="dialog-actions">${btn('匯出目前 TXT','export-txt',{icon:'download'})}${btn('取消','close-dialog')}${btn('選擇取代檔案','reload-confirmed',{class:'primary'})}</div>`);return;}$('#file-picker').dataset.mode=act;$('#file-picker').click();return;}
 if(act==='reload-confirmed'){$('#dialog').close();$('#file-picker').dataset.mode='reload-txt';$('#file-picker').click();return;}
 if(act==='extract'){const start=Number($('#pdf-start').value),end=Number($('#pdf-end').value);if(!Number.isInteger(start)||!Number.isInteger(end)||start<1||end>120||start>end){$('#source-error').textContent='請輸入整數，且符合 1 ≤ 起始頁 ≤ 結束頁 ≤ 120。';return;}const n=batch('b'+(++serial),`新批次・第 ${start}–${end} 頁`,'PDF',start,end,'');Object.assign(n,state.defaults);state.batches.push(n);state.selected=n.id;startJob('extract',n.id);return;}
 if(act==='page'){state.page=Number(id);render();return;}if(act==='show-page'){openDialog(`<div class="row between"><h2>示範原頁 · PDF 第 ${state.page} 頁</h2>${btn('關閉','close-dialog')}</div>${paper()}<p class="meta">此為原型排版，非實際 PDF 影像。</p>`);return;}
 if(act==='resolve-page'){b.unresolved=[];render();toast('這一批的異常頁已明確確認；現在可以確認朗讀稿。');return;}
 if(act==='confirm'){if(b.unresolved.length||!b.text.trim())return;b.confirmed=b.rev;b.saved=true;render();toast(`已固定本批朗讀稿 v${b.rev}，後續編輯不會改動這份快照。`);return;}
 if(act==='undo'){b.text=b.original;edited(b);render();toast('已回復示範原文，需重新確認朗讀稿。');return;}
 if(act==='save'){b.saved=true;render();toast('原型已暫存在記憶體；重新整理會重設，不會寫入專案檔。');return;}
 if(act==='export-txt'){const blob=new Blob([b.text],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=b.name+'_原型校對稿.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已匯出目前示範校對稿 TXT。');return;}
 if(act==='gemini'){startJob('gemini');return;}if(act==='accept-candidate'){if(!b.candidate)return;if(b.candidate.baseRev!==b.rev){toast('原稿版本已變更，候選保留，但不能直接覆蓋新稿。');return;}b.text=b.candidate.text;b.candidate.status='accepted';edited(b);render();toast('建議已採用；尚未確認為朗讀稿。');return;}
 if(act==='reject-candidate'){b.candidate.status='rejected';render();toast('已拒絕這一段建議，校對稿不變。');return;}
 if(act==='play'){state.play=!state.play;render();if(state.play){toast('模擬試聽狀態：不播放真實人聲。');setTimeout(()=>{state.play=false;render();},3500);}return;}
 if(act==='preset-natural'||act==='preset-relaxed'){b.sentence=act==='preset-natural'?0:200;b.paragraph=act==='preset-natural'?500:800;render();toast('已更新本批節奏；既有成品依設定判斷是否待更新。');return;}
 if(act==='set-defaults'){state.defaults={voice:b.voice,rate:b.rate,sentence:b.sentence,paragraph:b.paragraph};render();toast('全書預設已更新；其他既有批次設定保持不變。');return;}
 if(act==='generate-audio'){if(b.confirmed!==b.rev)return;startJob('audio');return;}if(act==='generate-video'){if(!validAudio(b))return;startJob('video');return;}if(act==='generate-merge'){if(!ordered().length||ordered().some(x=>!validVideo(x)))return;startJob('merge');return;}
 if(act==='media-image'||act==='media-video'){b.media=act==='media-image'?'image':'video';render();return;}if(act==='change-media'){b.mediaAlt=!b.mediaAlt;render();toast('已切換示範封面版本，音訊保持有效；尚未重新產生影片。');return;}
 if(act==='cancel-job'){if(state.job?.status==='running'){state.job.status='cancelled';clearTimeout(tickJob.timer);render();toast('已取消模擬任務，完成的區塊進度保留。');}return;}
 if(act==='resume-job'){if(state.job?.status==='cancelled'){state.job.status='running';render();tickJob();toast('從已完成的區塊之後繼續。');}return;}
 if(act==='move-up'||act==='move-down'){const i=state.mergeIds.indexOf(id),j=i+(act==='move-up'?-1:1);if(i>=0&&j>=0&&j<state.mergeIds.length){[state.mergeIds[i],state.mergeIds[j]]=[state.mergeIds[j],state.mergeIds[i]];render();}return;}
 if(act==='apply-gap'){state.gap=Math.round(Math.min(5,Math.max(0,Number($('#gap').value)||0))*10)/10;render();toast('交接額外停頓已套用：'+state.gap+' 秒。');return;}
 if(act==='edit-join'){state.selected=id;setStage('proof');return;}if(act==='preview-join'){previewJoin();return;}if(act==='play-join'){const c=$('#join-caption');c.textContent=`前批結束 → 額外靜音 ${state.gap}s`;setTimeout(()=>{if($('#join-caption'))$('#join-caption').textContent='下一批開始 → 字幕依偏移出現';},state.gap*1000+700);return;}
 if(act==='settings'){settingsDialog();return;}if(act==='close-dialog'){$('#dialog').close();return;}if(act==='test-gemini'){state.gemini.connected=true;toast('示範連線測試完成，沒有呼叫 Gemini。');return;}if(act==='save-settings'){state.gemini.model=$('#gemini-model')?.value||state.gemini.model;$('#dialog').close();render();toast('原型設定已暫存於記憶體。');return;}
 if(act==='scenario-stale'){const target=state.batches.find(x=>x.id==='b1');target.text+='\n\n（原型：修改一段文字）';target.rev++;target.confirmed=null;state.selected='b1';setStage('merge');toast('第一批已改稿：原批影片與使用它的總影片均待更新。');return;}
 if(act==='reset'){location.reload();return;}
});
document.addEventListener('input',e=>{if(e.target.id==='draft-editor'){const b=current();b.text=e.target.value;edited(b);}});
document.addEventListener('change',e=>{const target=e.target,b=current();if(target.dataset.mergeId){if(target.checked&&!state.mergeIds.includes(target.dataset.mergeId))state.mergeIds.push(target.dataset.mergeId);else if(!target.checked)state.mergeIds=state.mergeIds.filter(id=>id!==target.dataset.mergeId);render();return;}const keys={voice:'voice',rate:'rate',sentence:'sentence',paragraph:'paragraph',resolution:'resolution','video-mode':'mode'};if(keys[target.id]){if(target.id==='sentence'||target.id==='paragraph'){const max=target.id==='sentence'?1500:3000;b[keys[target.id]]=Math.min(max,Math.max(0,Number(target.value)||0));}else b[keys[target.id]]=target.value;render();return;}if(target.id==='gap'){state.gap=Math.round(Math.min(5,Math.max(0,Number(target.value)||0))*10)/10;render();return;}if(target.id==='total-resolution'){state.totalResolution=target.value;render();}});
$('#file-picker').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;const text=await file.text();if(e.target.dataset.mode==='reload-txt'){current().text=text;edited(current());toast('已重新載入 TXT，需重新確認朗讀稿。');}else{const n=batch('b'+(++serial),file.name.replace(/\.txt$/i,''),'TXT',null,null,text);Object.assign(n,state.defaults);state.batches.push(n);state.selected=n.id;state.stage='proof';toast('TXT 只在此頁面讀取，沒有上傳或永久保存。');}e.target.value='';render();});
document.addEventListener('keydown',e=>{if(e.key!=='ArrowLeft'&&e.key!=='ArrowRight')return;if(e.target.closest('input,textarea,select,[contenteditable="true"]')||$('#dialog').open)return;e.preventDefault();variant(['A','B','C'][(['A','B','C'].indexOf(state.variant)+(e.key==='ArrowRight'?1:2))%3]);});
window.addEventListener('popstate',()=>{const p=new URLSearchParams(location.search);if(['A','B','C'].includes(p.get('variant')))state.variant=p.get('variant');render();});
render();
